"""Summarize controlled TTGIR layout edits and counter/latency tradeoffs."""
import json
from .weights import ROOT

def main():
 root=ROOT/'artifacts/video_runtime_v1/tail_layout_v1';rows=[]
 for name in ('phase1','blocked','paired'):
  r=json.loads((root/(name+'_result.json')).read_text());rows.append(dict(variant=name,baseline_ms=r['median_ms']['jit'],candidate_ms=r['median_ms'][name],speedup=r['speedup'],equal=all(x['equal'] for x in r['contracts'][name]),resources=r['resources'][name],ir_control_equal=all(x['equal'] for x in r['contracts']['ir_control'])))
 assert all(r['equal'] and r['ir_control_equal'] for r in rows)
 (root/'summary.json').write_text(json.dumps(dict(rows=rows,deployed=False,scope='real P432 layer15 chunk8 step0 input; layout-only TTGIR edits; existing accepted runtime unchanged'),indent=2)+'\n')
 lines=['# 补偿共享布局：编译器IR原型与硬件复核','','## 本轮结论','','保留原补偿kernel。三种布局改写输出均逐位一致；最好的成对列布局在充分预热后仅获得约1%补偿模块收益，并将部分shared-store冲突转移为shared-load冲突。暂不把依赖Triton3.2内部IR的改写接入部署，也不为约2ms/短视频量级的候选启动三档视频验收。','', '| 原型 | 原版/ms | 候选/ms | 加速比 | mean/detail/LSE逐位一致 | 寄存器 | shared/B |','|---|---:|---:|---:|---|---:|---:|']
 for r in rows:lines.append(f"| {r['variant']} | {r['baseline_ms']:.6f} | {r['candidate_ms']:.6f} | {r['speedup']:.4f}× | {r['equal']} | {r['resources']['registers']} | {r['resources']['shared']} |")
 lines+=['', '所有原型与本次同进程JIT原版交错计时；不同原型启动时GPU状态不同，不跨行比较绝对ms。paired先取得1.7%初测收益，随后每版额外重放500次充分预热，再做50轮交错计时，每轮10次，稳态为0.450048→0.445645ms，1.00988×。原始初测单独保存在paired_initial_result.json。','', '## 严格限制改动范围','','捕获真实P432输入，保持BQ64/BR64、四warps、两stages、所有算术和归约操作，只编辑最终TTGIR的布局描述符。使用未改IR重新编译作为控制，其mean/detail/LSE与JIT原版逐位一致。','', '- phase1：只把BF16中间矩阵shared布局perPhase4改为1。输出一致，但回退。','- blocked：把R4归约前后的线程持有布局从M4、较多列线程改成M1、更多行线程；shared减少8KiB，输出一致，但未提速。','- paired：基于blocked，让每线程持有两个相邻页面系数，使两个BF16值有机会一起写入32bit shared word。shared略增1KiB，得到小幅收益。','', '该实验只覆盖一个真实满窗口事件，不宣称其他P、所有层或所有视频已验证。没有改全局Triton安装。读取TTGIR时发现Triton3.2的贪婪函数签名正则在带location的文本上长时间回溯；用6秒有界独立解析和faulthandler栈确认位于re.search，实验进程内替换为针对单行函数头和指针参数的解析式，再进行原版IR控制。','', '## bank conflict下降不等于同比例提速','','| 版本 | shared-store conflicts | shared-load conflicts |','|---|---:|---:|','| 原版 | 9,545,193 | 49,813 |','| blocked | 4,659,563 | 33,242 |','| paired | 692,897 | 3,054,166 |','', 'paired的store冲突约下降92.7%，load冲突约增至61倍。此处是硬件事件计数，不能把两类事件数量直接折算成延迟。寄存器仍255/thread，整体并发没有突破；额外load转换、同步及Tensor Core依赖仍存在。blocked即使减少约一半store冲突也没有时延改善，因此不应继续把原约955万冲突当作一笔可直接收回的时间预算。','', '## 端到端收益量级','','P432单次约省4.4us。9chunks三档有464次满窗口补偿调用，按已测范围线性估计约2.04ms，相对约7.5–8.3s生成仅0.025%–0.027%。这还未验证运行时接口成本和其他P表现，不值得为了这个量级引入内部IR编译依赖。精算、补偿和路由的原算法预算完全不变。','', '## 下一步依据','','重新检查稳定softmax基线的完整chunk8 timeline：GPU span955.909ms，kernel/memcpy/memset区间并集926.642ms，空隙29.267ms（3.06%）。这是插桩后的诊断，不能全当可回收Python时间；但它比此次约2ms/整视频的布局候选有更大的验证空间。下一项可对现有block_graph做保持summary实现和三档分支隔离的单次原型，先解决inline_summary切换及graph key问题，再看净收益，不直接开启旧开关。','', '## 代码和证据','','- [布局原型与计时](../../../local_experiments/video_runtime_v1/check_tail_layout.py)：`--variant phase1|blocked|paired`。','- [Nsight入口](../../../local_experiments/video_runtime_v1/profile_tail_layout.py)：`--variant blocked|paired|phase1`。','- [phase1结果](phase1_result.json)、[blocked结果](blocked_result.json)、[paired稳态](paired_result.json)、[paired初测](paired_initial_result.json)。','- [blocked计数](blocked_stalls.csv)、[paired计数](paired_conflicts.csv)。','- 本目录baseline/phase1/blocked/paired.ttgir保存原始及修改后的编译器IR，PTX保留编译结果；输入复用上一轮tail_liveness_v1/input.pt。','', '本轮无部署变更、无新增视频生成、无15s/30s质量测试。']
 (root/'MODULE_DISTANCE.zh.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
